-- Rasikh database foundation.
-- This migration creates only identity, tenant hierarchy, memberships, student links,
-- enrollment history, and sync idempotency receipts. Educational scoring fields remain
-- out until the approved teaching rules are mapped to a relational model.
--
-- UUID primary keys are generated by the application to avoid requiring a PostgreSQL
-- extension or elevated database privileges.

CREATE TABLE public.associations (
  id uuid PRIMARY KEY,
  name text NOT NULL CHECK (length(btrim(name)) > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.branches (
  id uuid PRIMARY KEY,
  association_id uuid NOT NULL,
  name text NOT NULL CHECK (length(btrim(name)) > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT branches_association_fk
    FOREIGN KEY (association_id)
    REFERENCES public.associations (id)
    ON DELETE RESTRICT,

  CONSTRAINT branches_id_association_unique
    UNIQUE (id, association_id)
);

CREATE TABLE public.quranic_premises (
  id uuid PRIMARY KEY,
  association_id uuid NOT NULL,
  branch_id uuid NOT NULL,
  name text NOT NULL CHECK (length(btrim(name)) > 0),
  description text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT quranic_premises_branch_fk
    FOREIGN KEY (branch_id, association_id)
    REFERENCES public.branches (id, association_id)
    ON DELETE RESTRICT,

  CONSTRAINT quranic_premises_id_association_unique
    UNIQUE (id, association_id)
);

CREATE TABLE public.circles (
  id uuid PRIMARY KEY,
  association_id uuid NOT NULL,
  quranic_premise_id uuid NOT NULL,
  name text NOT NULL CHECK (length(btrim(name)) > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT circles_quranic_premise_fk
    FOREIGN KEY (quranic_premise_id, association_id)
    REFERENCES public.quranic_premises (id, association_id)
    ON DELETE RESTRICT,

  CONSTRAINT circles_id_association_unique
    UNIQUE (id, association_id)
);

CREATE TABLE public.persons (
  id uuid PRIMARY KEY,
  full_name text NOT NULL CHECK (length(btrim(full_name)) > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.user_accounts (
  id uuid PRIMARY KEY,
  person_id uuid NOT NULL UNIQUE,
  status text NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'active', 'disabled')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT user_accounts_person_fk
    FOREIGN KEY (person_id)
    REFERENCES public.persons (id)
    ON DELETE RESTRICT,

  CONSTRAINT user_accounts_id_person_unique
    UNIQUE (id, person_id)
);

CREATE TABLE public.association_memberships (
  id uuid PRIMARY KEY,
  association_id uuid NOT NULL,
  person_id uuid NOT NULL,
  status text NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'active', 'suspended', 'ended')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT memberships_association_fk
    FOREIGN KEY (association_id)
    REFERENCES public.associations (id)
    ON DELETE RESTRICT,

  CONSTRAINT memberships_person_fk
    FOREIGN KEY (person_id)
    REFERENCES public.persons (id)
    ON DELETE RESTRICT,

  CONSTRAINT memberships_person_association_unique
    UNIQUE (association_id, person_id),

  CONSTRAINT memberships_id_association_person_unique
    UNIQUE (id, association_id, person_id)
);

-- role_code stays open until the detailed role/permission matrix is approved.
-- Scope columns and composite foreign keys prevent assigning a role to a unit in
-- another association. A circle is attached through its Qur'anic premise.
CREATE TABLE public.role_assignments (
  id uuid PRIMARY KEY,
  association_id uuid NOT NULL,
  membership_id uuid NOT NULL,
  role_code text NOT NULL CHECK (length(btrim(role_code)) BETWEEN 1 AND 64),
  scope_type text NOT NULL
    CHECK (scope_type IN ('association', 'branch', 'quranic_premise', 'circle')),
  branch_id uuid,
  quranic_premise_id uuid,
  circle_id uuid,
  valid_from timestamptz NOT NULL DEFAULT now(),
  valid_until timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT role_assignments_membership_fk
    FOREIGN KEY (membership_id, association_id)
    REFERENCES public.association_memberships (id, association_id)
    ON DELETE RESTRICT,

  CONSTRAINT role_assignments_branch_scope_fk
    FOREIGN KEY (branch_id, association_id)
    REFERENCES public.branches (id, association_id)
    ON DELETE RESTRICT,

  CONSTRAINT role_assignments_premise_scope_fk
    FOREIGN KEY (quranic_premise_id, association_id)
    REFERENCES public.quranic_premises (id, association_id)
    ON DELETE RESTRICT,

  CONSTRAINT role_assignments_circle_scope_fk
    FOREIGN KEY (circle_id, association_id)
    REFERENCES public.circles (id, association_id)
    ON DELETE RESTRICT,

  CONSTRAINT role_assignments_scope_shape_check
    CHECK (
      (scope_type = 'association'
        AND branch_id IS NULL
        AND quranic_premise_id IS NULL
        AND circle_id IS NULL)
      OR
      (scope_type = 'branch'
        AND branch_id IS NOT NULL
        AND quranic_premise_id IS NULL
        AND circle_id IS NULL)
      OR
      (scope_type = 'quranic_premise'
        AND branch_id IS NULL
        AND quranic_premise_id IS NOT NULL
        AND circle_id IS NULL)
      OR
      (scope_type = 'circle'
        AND branch_id IS NULL
        AND quranic_premise_id IS NULL
        AND circle_id IS NOT NULL)
    ),

  CONSTRAINT role_assignments_validity_check
    CHECK (valid_until IS NULL OR valid_until > valid_from)
);

CREATE TABLE public.students (
  id uuid PRIMARY KEY,
  association_id uuid NOT NULL,
  person_id uuid NOT NULL,
  status text NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'inactive', 'archived')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT students_person_fk
    FOREIGN KEY (person_id)
    REFERENCES public.persons (id)
    ON DELETE RESTRICT,

  CONSTRAINT students_association_fk
    FOREIGN KEY (association_id)
    REFERENCES public.associations (id)
    ON DELETE RESTRICT,

  CONSTRAINT students_person_association_unique
    UNIQUE (association_id, person_id),

  CONSTRAINT students_id_association_unique
    UNIQUE (id, association_id)
);

CREATE TABLE public.guardian_student_links (
  id uuid PRIMARY KEY,
  association_id uuid NOT NULL,
  guardian_membership_id uuid NOT NULL,
  student_id uuid NOT NULL,
  relationship_code text NOT NULL
    CHECK (length(btrim(relationship_code)) BETWEEN 1 AND 64),
  valid_from timestamptz NOT NULL DEFAULT now(),
  valid_until timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT guardian_student_membership_fk
    FOREIGN KEY (guardian_membership_id, association_id)
    REFERENCES public.association_memberships (id, association_id)
    ON DELETE RESTRICT,

  CONSTRAINT guardian_student_student_fk
    FOREIGN KEY (student_id, association_id)
    REFERENCES public.students (id, association_id)
    ON DELETE RESTRICT,

  CONSTRAINT guardian_student_validity_check
    CHECK (valid_until IS NULL OR valid_until > valid_from)
);

CREATE TABLE public.student_circle_enrollments (
  id uuid PRIMARY KEY,
  association_id uuid NOT NULL,
  student_id uuid NOT NULL,
  circle_id uuid NOT NULL,
  started_at timestamptz NOT NULL DEFAULT now(),
  ended_at timestamptz,
  recorded_by_membership_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT student_enrollment_student_fk
    FOREIGN KEY (student_id, association_id)
    REFERENCES public.students (id, association_id)
    ON DELETE RESTRICT,

  CONSTRAINT student_enrollment_circle_fk
    FOREIGN KEY (circle_id, association_id)
    REFERENCES public.circles (id, association_id)
    ON DELETE RESTRICT,

  CONSTRAINT student_enrollment_recorder_fk
    FOREIGN KEY (recorded_by_membership_id, association_id)
    REFERENCES public.association_memberships (id, association_id)
    ON DELETE RESTRICT,

  CONSTRAINT student_enrollment_validity_check
    CHECK (ended_at IS NULL OR ended_at > started_at)
);

-- Stores only the idempotency receipt, not the offline payload. The actual
-- attendance/recitation row and this receipt must be committed in one transaction
-- by the future sync handler. The browser retains payloads that need review.
CREATE TABLE public.sync_operation_receipts (
  id uuid PRIMARY KEY,
  association_id uuid NOT NULL,
  membership_id uuid NOT NULL,
  account_id uuid NOT NULL,
  person_id uuid NOT NULL,
  device_instance_id uuid NOT NULL,
  client_operation_id uuid NOT NULL,
  operation_type text NOT NULL
    CHECK (operation_type IN ('attendance.record', 'recitation.record')),
  payload_sha256 char(64) NOT NULL
    CHECK (payload_sha256 ~ '^[0-9a-f]{64}$'),
  outcome text NOT NULL
    CHECK (outcome IN ('accepted', 'conflict', 'rejected')),
  result_code text,
  client_created_at timestamptz,
  received_at timestamptz NOT NULL DEFAULT now(),
  processed_at timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT sync_receipts_membership_fk
    FOREIGN KEY (membership_id, association_id, person_id)
    REFERENCES public.association_memberships (id, association_id, person_id)
    ON DELETE RESTRICT,

  CONSTRAINT sync_receipts_account_fk
    FOREIGN KEY (account_id, person_id)
    REFERENCES public.user_accounts (id, person_id)
    ON DELETE RESTRICT,

  CONSTRAINT sync_receipts_operation_unique
    UNIQUE (association_id, client_operation_id),

  CONSTRAINT sync_receipts_result_code_check
    CHECK (
      (outcome = 'accepted' AND result_code IS NULL)
      OR
      (outcome IN ('conflict', 'rejected') AND result_code IS NOT NULL)
    )
);

CREATE INDEX branches_association_idx
  ON public.branches (association_id);

CREATE INDEX quranic_premises_branch_idx
  ON public.quranic_premises (association_id, branch_id);

CREATE INDEX circles_quranic_premise_idx
  ON public.circles (association_id, quranic_premise_id);

CREATE INDEX memberships_person_idx
  ON public.association_memberships (person_id, status);

CREATE INDEX role_assignments_membership_idx
  ON public.role_assignments (association_id, membership_id, valid_until);

CREATE INDEX role_assignments_branch_scope_idx
  ON public.role_assignments (association_id, branch_id)
  WHERE branch_id IS NOT NULL;

CREATE INDEX role_assignments_premise_scope_idx
  ON public.role_assignments (association_id, quranic_premise_id)
  WHERE quranic_premise_id IS NOT NULL;

CREATE INDEX role_assignments_circle_scope_idx
  ON public.role_assignments (association_id, circle_id)
  WHERE circle_id IS NOT NULL;

CREATE INDEX students_association_status_idx
  ON public.students (association_id, status);

CREATE INDEX guardian_student_student_idx
  ON public.guardian_student_links (association_id, student_id);

CREATE INDEX guardian_student_membership_idx
  ON public.guardian_student_links (association_id, guardian_membership_id);

CREATE INDEX student_enrollments_student_history_idx
  ON public.student_circle_enrollments (association_id, student_id, started_at DESC);

CREATE INDEX student_enrollments_circle_history_idx
  ON public.student_circle_enrollments (association_id, circle_id, started_at DESC);

CREATE INDEX sync_receipts_membership_received_idx
  ON public.sync_operation_receipts (association_id, membership_id, received_at DESC);

CREATE INDEX sync_receipts_device_received_idx
  ON public.sync_operation_receipts (device_instance_id, received_at DESC);
